const SUPABASE_URL="https://wrmdmcbaylowomxhgybd.supabase.co";
const SUPABASE_PUBLISHABLE_KEY="sb_publishable_oA62PAqwIE1vM6o13_Cd_Q_sfx-3buu";
let sb=null;
let sbAuthListenerAttached=false;

function attachSupabaseAuthListener(){
 if(!sb || sbAuthListenerAttached)return;
 sbAuthListenerAttached=true;
 sb.auth.onAuthStateChange((event,session)=>{
   onlineSession=session||null;
   if(event==='PASSWORD_RECOVERY'){
     showPasswordRecoveryForm();
     return;
   }
   if(event==='SIGNED_OUT' && !document.querySelector('.cinema-screen'))showOnlineAuth();
 });
}

function initSupabaseClient(){
 if(sb)return true;
 if(!(window.supabase&&window.supabase.createClient))return false;
 try{
   sb=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{
     auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}
   });
   attachSupabaseAuthListener();
   const failed=document.querySelector('.online-loader');
   if(failed && /Supabase istemcisi|Online bağlantı yüklenemedi/.test(failed.textContent||''))showOnlineAuth();
   return true;
 }catch(e){console.warn('Supabase init',e);return false}
}

function loadSupabaseClientAsync(){
 if(initSupabaseClient())return;
 const urls=[
   'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2',
   'https://unpkg.com/@supabase/supabase-js@2'
 ];
 const tryNext=(i)=>{
   if(i>=urls.length){console.warn('Supabase CDN yüklenemedi');return}
   const sc=document.createElement('script');
   sc.src=urls[i];sc.async=true;sc.crossOrigin='anonymous';
   sc.onload=()=>{if(!initSupabaseClient())tryNext(i+1)};
   sc.onerror=()=>tryNext(i+1);
   document.head.appendChild(sc);
 };
 tryNext(0);
}


