function esc(v){
 return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function onlineErrText(err){
 const s=(err&&err.message?err.message:String(err||'')).toLowerCase();
 if(s.includes('invalid login'))return 'E-posta veya şifre yanlış.';
 if(s.includes('email not confirmed'))return 'Önce e-posta adresini doğrulamalısın.';
 if(s.includes('username already taken'))return 'Bu rumuz başka bir oyuncuda.';
 if(s.includes('invalid username'))return 'Rumuz 3-18 karakter olmalı. Harf, rakam, boşluk ve alt çizgi kullanılabilir.';
 if(s.includes('database error saving new user'))return 'Rumuz kullanılıyor olabilir veya kayıt bilgileri uygun değil.';
 if(s.includes('rate limit'))return 'Çok hızlı işlem yaptın. Biraz sonra tekrar dene.';
 if(s.includes('network')||s.includes('fetch'))return 'Sunucuya ulaşılamadı. İnternet bağlantını kontrol et.';
 return err&&err.message?err.message:'Beklenmeyen bir bağlantı hatası oluştu.';
}
function setAuthMessage(type,msg){
 const e=document.getElementById('authError'),s=document.getElementById('authSuccess');
 if(e){e.style.display=type==='error'?'block':'none';e.textContent=msg||''}
 if(s){s.style.display=type==='success'?'block':'none';s.textContent=msg||''}
}
function setAuthMode(mode){
 authMode=mode;showOnlineAuth();
}
function selectSignupGender(g){
 signupGender=g;
 document.getElementById('gMale')?.classList.toggle('on',g==='male');
 document.getElementById('gFemale')?.classList.toggle('on',g==='female');
}
