    <div class="auth-field"><label>Karakter</label><div class="gender-pick"><button id="gMale" class="${signupGender==='male'?'on':''}" onclick="selectSignupGender('male')">👤 ERKEK</button><button id="gFemale" class="${signupGender==='female'?'on':''}" onclick="selectSignupGender('female')">👩 KADIN</button></div></div>
