function showOnlineRulesStandalone(){
 document.getElementById('app').innerHTML=`<section class="game"><div class="shell"><main class="content" style="max-width:1000px;margin:auto">${rulesView().replace("onclick=\"go('home')\"","onclick=\"showOnlineAuth()\"")}</main></div></section>`;
}
async function registerOnline(){
 if(onlineBusy)return;
 const username=(document.getElementById('regUsername')?.value||'').trim();
 const email=(document.getElementById('regEmail')?.value||'').trim();
 const password=document.getElementById('regPassword')?.value||'';
 setAuthMessage('', '');
 if(username.length<3||username.length>18){setAuthMessage('error','Rumuz 3 ile 18 karakter arasında olmalı.');return}
 if(!email.includes('@')){setAuthMessage('error','Geçerli bir e-posta adresi yaz.');return}
 if(password.length<8){setAuthMessage('error','Şifre en az 8 karakter olmalı.');return}
 onlineBusy=true;
 const btn=document.getElementById('authMainBtn');if(btn)btn.textContent='KONTROL EDİLİYOR...';
 try{
   const avail=await sb.rpc('username_available',{p_username:username});
   if(avail.error)throw avail.error;
   if(avail.data!==true){setAuthMessage('error','Bu rumuz başka bir oyuncuda.');return}
   if(btn)btn.textContent='HESAP AÇILIYOR...';
   const {data,error}=await sb.auth.signUp({
     email,password,
     options:{data:{username,gender:signupGender}}
   });
   if(error)throw error;
   if(data.session){
     onlineSession=data.session;
     await loadOnlineAccount(true);
   }else{
     setAuthMessage('success','Hesap oluşturuldu. E-postana gelen doğrulama bağlantısını aç, ardından buradan giriş yap.');
     authMode='login';
   }
 }catch(e){setAuthMessage('error',onlineErrText(e))}
 finally{onlineBusy=false;if(btn)btn.textContent='HESABI OLUŞTUR'}
}
async function signInOnline(){
 if(onlineBusy)return;
 const email=(document.getElementById('authEmail')?.value||'').trim();
 const password=document.getElementById('authPassword')?.value||'';
 if(!email||!password){setAuthMessage('error','E-posta ve şifreni yaz.');return}
 onlineBusy=true;const btn=document.getElementById('authMainBtn');if(btn)btn.textContent='BAĞLANIYOR...';
 try{
   const {data,error}=await sb.auth.signInWithPassword({email,password});
   if(error)throw error;
   onlineSession=data.session;
   await loadOnlineAccount(true);
 }catch(e){setAuthMessage('error',onlineErrText(e))}
 finally{onlineBusy=false;if(btn)btn.textContent="İSTANBUL'A GİR"}
}
function passwordResetRedirectUrl(){
 try{
   const u=new URL(window.location.href);
   if(u.protocol!=='https:' || ['localhost','127.0.0.1'].includes(u.hostname)) return null;
   u.hash='';u.search='';
   u.searchParams.set('recovery','1');
   return u.toString();
 }catch(_){return null}
}
