async function saveRecoveredPassword(){
 const p1=document.getElementById('newPassword1')?.value||'';
 const p2=document.getElementById('newPassword2')?.value||'';
 if(p1.length<8){setAuthMessage('error','Yeni şifre en az 8 karakter olmalı.');return}
 if(p1!==p2){setAuthMessage('error','Yazdığın iki şifre aynı değil.');return}
 const btn=document.getElementById('passwordSaveBtn');if(btn)btn.textContent='KAYDEDİLİYOR...';
 try{
   const {error}=await sb.auth.updateUser({password:p1});
   if(error)throw error;
   setAuthMessage('success','Şifren değiştirildi. Giriş ekranına dönüyorsun...');
   try{history.replaceState({},document.title,location.pathname)}catch(_){ }
   setTimeout(async()=>{await sb.auth.signOut();authMode='login';showOnlineAuth()},900);
 }catch(e){setAuthMessage('error',onlineErrText(e));if(btn)btn.textContent='YENİ ŞİFREYİ KAYDET'}
}
async function forgotPasswordOnline(){
 const email=(document.getElementById('authEmail')?.value||'').trim();
 if(!email){setAuthMessage('error','Önce e-posta adresini yaz.');return}
 const redirectTo=passwordResetRedirectUrl();
 if(!redirectTo){
   setAuthMessage('error','Şifre sıfırlama canlı HTTPS oyun linkinde çalışır. Oyunu yayınlanan linkten açıp tekrar dene.');
   return;
 }
 try{
  const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo});
  if(error)throw error;
  setAuthMessage('success','Şifre yenileme bağlantısı e-posta adresine gönderildi. E-postadaki bağlantıya dokun.');
 }catch(e){setAuthMessage('error',onlineErrText(e))}
}
async function onlineGate(){
 if(!sb){showOnlineAuth();return}
 document.getElementById('app').innerHTML=`<section class="online-loader"><div><div class="spinner"></div><b>İstanbul'a bağlanılıyor...</b><p class="small">Sunucu kaydın ve şehir durumu kontrol ediliyor.</p></div></section>`;
 try{
   const {data,error}=await sb.auth.getSession();
   if(error)throw error;
   onlineSession=data.session||null;
   if(!onlineSession){showOnlineAuth();return}
   await loadOnlineAccount(true);
 }catch(e){
   onlineSession=null;showOnlineAuth();setAuthMessage('error',onlineErrText(e));
 }
}
function applyOnlineState(prof,row){
 onlineProfile=prof||onlineProfile;
 onlineServerState=row||onlineServerState;
 if(prof){
   state.name=prof.username||prof.display_name||'Oyuncu';
   state.gender=prof.gender||'male';
   state.city=prof.city||'İstanbul';
   state.district=prof.district||'Karaköy';
   state.rank=prof.rank||'Sokak Çocuğu';
   state.rep=Number(prof.reputation||0);
 }
 if(row){
   state.cash=Number(row.cash||0);state.bank=Number(row.bank||0);state.energy=Number(row.energy||0);
   state.hp=Number(row.hp||0);state.heat=Number(row.heat||0);state.generation=Number(row.generation||1);
   state.jailUntil=row.jail_until?Date.parse(row.jail_until):0;
   state.hospitalUntil=row.hospital_until?Date.parse(row.hospital_until):0;
   state.dead=!!row.dead;state.heirAvailableAt=row.heir_available_at?Date.parse(row.heir_available_at):0;
   state.executionCooldownUntil=row.execution_cooldown_until?Date.parse(row.execution_cooldown_until):0;
   state.pvpCooldownUntil=row.pvp_cooldown_until?Date.parse(row.pvp_cooldown_until):0;
   state.jobsDone=Number(row.jobs_done||0);state.kills=Number(row.kills||0);state.deaths=Number(row.deaths||0);
   state.executions=Number(row.executions||0);state.arrests=Number(row.arrests||0);state.convictions=Number(row.convictions||0);
   state.acquittals=Number(row.acquittals||0);state.awaitingTrial=!!row.awaiting_trial;
   state.rank=row.rank||state.rank;state.rep=Number(row.reputation??state.rep);
 }
 state.introDone=true;state.online=true;
 save();
}
async function loadOnlineAccount(enter=true){
 if(!onlineSession)return;
 document.getElementById('app').innerHTML=`<section class="online-loader"><div><div class="spinner"></div><b>Karakter yükleniyor...</b><p class="small">Para, itibar, rütbe ve çevrimiçi durum sunucudan alınıyor.</p></div></section>`;
 try{
   const uid=onlineSession.user.id;
   const [profRes,stateRes,famRes,premiumRes,relRes,garageRes,propsRes]=await Promise.all([
     sb.from('profiles').select('id,username,display_name,gender,city,district,rank,reputation,last_seen').eq('id',uid).single(),
     sb.rpc('my_online_state'),
     sb.rpc('my_family'),
     sb.rpc('my_premium_state'),
     sb.rpc('my_relationship_state'),
     sb.rpc('my_garage_inventory'),
     sb.from('player_properties').select('id,property_id,acquired_at').eq('user_id',uid)
   ]);
   if(profRes.error)throw profRes.error;
   if(stateRes.error)throw stateRes.error;
   const row=Array.isArray(stateRes.data)?stateRes.data[0]:stateRes.data;
   applyOnlineState(profRes.data,row);
   const frow=Array.isArray(famRes.data)&&famRes.data.length?famRes.data[0]:null;
   onlineFamily=frow?{id:frow.family_id,name:frow.family_name,role:frow.role}:null;
   state.family=onlineFamily?onlineFamily.name:null;state.familyRole=onlineFamily?onlineFamily.role:null;
   state.customFamily=null;
   state.properties=(!propsRes.error&&Array.isArray(propsRes.data))?propsRes.data:[];
   if(!premiumRes.error&&premiumRes.data){
     onlinePremiumState=premiumRes.data;onlinePremiumLoaded=true;
     state.credits=Number(premiumRes.data.credits||0);
   }
   if(!relRes.error&&relRes.data){onlineRelationshipState=relRes.data;onlineRelationshipLoaded=true}
   const rel=(!relRes.error&&relRes.data)?relRes.data.relationship:null;
   state.spouse=rel&&rel.status==='married'?rel.partner_name:null;
   state.engagedTo=rel&&rel.status==='engaged'?rel.partner_name:null;
   const garage=(!garageRes.error&&garageRes.data)?garageRes.data:null;
   const activeVehicle=garage&&Array.isArray(garage.vehicles)?garage.vehicles.find(v=>v.active):null;
   state.car=activeVehicle?(activeVehicle.name||activeVehicle.vehicle_id):null;
   await Promise.all([touchOnlinePresence(),loadOnlinePlayers(false),loadOnlineChat(false),loadOnlinePvpTargets(false),loadOnlineFamilySetup(false),loadOnlineTerritory(false),loadOnlineSocial(false),loadOnlinePremium(false),loadOnlineNotifications(false),loadOnlineWorldNews(false),loadOnlineRankings(false),loadOnlineCouncil(false),loadOnlineGarage(false),loadOnlineOps(false),loadOnlineCemetery(false)]);
   subscribeOnlineRealtime();
   startOnlineHeartbeat();
   if(enter)enterGame();
 }catch(e){
   showOnlineAuth();setAuthMessage('error','Karakter yüklenemedi: '+onlineErrText(e));
 }
}
async function syncOnlineState(render=false){
 if(!onlineSession||onlineBusy)return;
 try{
   const [profRes,stateRes,famRes]=await Promise.all([
     sb.from('profiles').select('id,username,display_name,gender,city,district,rank,reputation,last_seen').eq('id',onlineSession.user.id).single(),
     sb.rpc('my_online_state'),
     sb.rpc('my_family')
   ]);
   if(profRes.error||stateRes.error)return;
   applyOnlineState(profRes.data,Array.isArray(stateRes.data)?stateRes.data[0]:stateRes.data);
   const frow=Array.isArray(famRes.data)&&famRes.data.length?famRes.data[0]:null;
   onlineFamily=frow?{id:frow.family_id,name:frow.family_name,role:frow.role}:null;
   state.family=onlineFamily?onlineFamily.name:null;state.familyRole=onlineFamily?onlineFamily.role:null;
   if(state.awaitingTrial)await loadOnlineCurrentCase(false);
   if(render)renderGame();
 }catch(e){console.warn('online sync',e)}
}
async function touchOnlinePresence(){
 if(!onlineSession||!onlineProfile)return;
 try{
  await sb.rpc('touch_presence',{p_city:state.city||'İstanbul',p_district:state.district||'Karaköy',p_rank:state.rank||'Sokak Çocuğu',p_reputation:Number(state.rep||0)});
 }catch(e){}
}
function startOnlineHeartbeat(){
 if(onlinePresenceTimer)clearInterval(onlinePresenceTimer);
 if(onlineSyncTimer)clearInterval(onlineSyncTimer);
 onlinePresenceTimer=setInterval(async()=>{
   await touchOnlinePresence();
   await loadOnlinePlayers(currentPage==='online');
   await loadOnlineFamilySetup(false);
   await loadOnlineTerritory(currentPage==='territories');
   await loadOnlineSocial(currentPage==='social');
   if(currentPage==='shop')await loadOnlinePremium(true);
   await loadOnlineNotifications(currentPage==='notifications');
   if(currentPage==='news')await loadOnlineWorldNews(true);
   if(currentPage==='ranking')await loadOnlineRankings(true);
   if(currentPage==='council')await loadOnlineCouncil(true);
   if(currentPage==='garage')await loadOnlineGarage(true);
   if(currentPage==='ops')await loadOnlineOps(true);
   if(currentPage==='cemetery')await loadOnlineCemetery(true);
 },60000);
 onlineSyncTimer=setInterval(()=>syncOnlineState(['home','profile','jobs','families'].includes(currentPage)),60000);
}
function subscribeOnlineRealtime(){
 if(!sb||!onlineSession)return;
 if(onlineRealtimeChannel)sb.removeChannel(onlineRealtimeChannel);
 onlineRealtimeChannel=sb.channel('kanunsuz-v12-live')
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'chat_messages'},()=>{
    if(currentPage==='chat')loadOnlineChat(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'profiles'},()=>{
    if(currentPage==='online')loadOnlinePlayers(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'marriage_proposals'},()=>{
    if(currentPage==='social')loadOnlineSocial(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'relationships'},()=>{
    if(currentPage==='social')loadOnlineSocial(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'wedding_invitations'},()=>{
    if(currentPage==='social')loadOnlineSocial(true);
 })
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'premium_gifts'},()=>{
    if(currentPage==='shop')loadOnlinePremium(true);
 })
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications'},()=>{
    loadOnlineNotifications(currentPage==='notifications');
 })
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'world_events'},()=>{
    loadOnlineWorldNews(currentPage==='news');
    if(currentPage==='council')loadOnlineCouncil(true);
    if(currentPage==='ranking')loadOnlineRankings(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'council_seats'},()=>{
    if(currentPage==='council')loadOnlineCouncil(true);
 })
 .on('postgres_changes',{event:'*',schema:'public',table:'council_motions'},()=>{
    if(currentPage==='council')loadOnlineCouncil(true);
 })
 .subscribe();
}
async function logoutOnline(){
 try{if(sb)await sb.auth.signOut()}catch(e){}
 onlineSession=null;onlineProfile=null;onlineServerState=null;onlineFamily=null;onlinePlayersCache=[];onlineChatCache=[];onlineChatPeer=null;onlinePvpTargets=[];onlinePvpTargetsLoaded=false;onlineFamilySetup=null;onlineFamilySetupLoaded=false;onlineCurrentCase=null;onlineCurrentCaseLoaded=false;onlineTerritoryMap=[];onlineTerritoryLoaded=false;onlineWarState=null;onlineWarLoaded=false;onlineRelationshipState=null;onlineRelationshipLoaded=false;onlineRelationshipCandidates=[];onlineRelationshipCandidatesLoaded=false;onlinePremiumState=null;onlinePremiumLoaded=false;onlineGiftCandidates=[];onlineGiftCandidatesLoaded=false;onlineNotifications=[];onlineNotificationsLoaded=false;onlineUnreadCount=0;onlineWorldNews=[];onlineWorldNewsLoaded=false;onlinePlayerRanking=[];onlineFamilyRanking=[];onlineRankingsLoaded=false;onlineCouncilState=null;onlineCouncilLoaded=false;onlineGarageState=null;onlineGarageLoaded=false;onlineOpsState=null;onlineOpsLoaded=false;onlineOpsStats={wins:0,losses:0};onlineCemeteryRecords=[];onlineCemeteryLoaded=false;
 if(onlineRealtimeChannel&&sb)sb.removeChannel(onlineRealtimeChannel);onlineRealtimeChannel=null;
 if(onlinePresenceTimer)clearInterval(onlinePresenceTimer);if(onlineSyncTimer)clearInterval(onlineSyncTimer);
 onlinePresenceTimer=null;onlineSyncTimer=null;
 state={...defaultState};save();authMode='login';bootIntro(true);
}
async function loadOnlinePlayers(render=true){
 if(!onlineSession)return;
 try{
   const {data,error}=await sb.rpc('online_players');
   if(error)throw error;
   onlinePlayersCache=Array.isArray(data)?data:[];
   onlinePlayersLoaded=true;
   if(render&&currentPage==='online')renderGame();
 }catch(e){console.warn(e)}
}
function onlineAgo(ts){
 const sec=Math.max(0,Math.floor((Date.now()-Date.parse(ts))/1000));
 if(sec<45)return 'şimdi';
 if(sec<120)return '1 dk önce';
 return Math.min(5,Math.floor(sec/60))+' dk önce';
}
function openOnlinePlayer(id){
 const p=onlinePlayersCache.find(x=>x.id===id);if(!p)return;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="onlinePlayerModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG['cin_intro_3.webp']}')">${rainHTML(18)}</div><div class="modal-content">
 <div class="kicker">ONLINE OYUNCU</div><h2>${esc(p.username||p.display_name)}</h2>
 <div class="job-meta"><span class="chip">${esc(p.rank)}</span><span class="chip">⭐ ${Number(p.reputation||0).toLocaleString('tr-TR')}</span><span class="chip">${esc(p.city)} • ${esc(p.district)}</span><span class="chip">🟢 ${onlineAgo(p.last_seen)}</span></div>
 <div class="modal-actions">${p.id!==onlineSession?.user?.id?`<button class="btn gold" onclick="startPrivateChat('${p.id}','${esc(p.username||p.display_name)}')">ÖZEL MESAJ</button>`:''}<button class="btn ghost" onclick="document.getElementById('onlinePlayerModal').remove()">KAPAT</button></div>
 </div></div></div>`);
}
function onlinePlayersView(){
 const me=onlineSession?.user?.id;
 const others=onlinePlayersCache.filter(p=>p.id!==me);
 return `<section class="card pad"><div class="section-head"><h2>Online Oyuncular</h2><span class="server-badge"><span class="online-dot"></span>${onlinePlayersCache.length} çevrimiçi</span></div>
 <div class="online-banner"><div><strong>GERÇEK SUNUCU BAĞLANTISI AKTİF</strong><div class="small">Buradaki oyuncular son 5 dakika içinde KANUNSUZ sunucusuna bağlı gerçek hesaplardır.</div></div><button class="btn ghost" onclick="loadOnlinePlayers(true)">↻ YENİLE</button></div>
 ${onlineProfile?`<div class="online-player" style="margin-bottom:10px;border-color:rgba(209,165,78,.34)"><img class="online-avatar" src="${IMG[state.gender==='female'?'avatar_female.webp':'avatar_male.webp']}"><div><h4>★ ${esc(state.name)} <span class="small">(Sen)</span></h4><p class="small">${esc(state.rank)} • ⭐ ${Number(state.rep).toLocaleString('tr-TR')} • ${esc(state.city)} / ${esc(state.district)}</p></div><span class="online-status-pill"><span class="online-dot"></span>Bağlı</span></div>`:''}
 <div style="display:grid;gap:9px">${others.length?others.map(p=>`<div class="online-player"><img class="online-avatar" src="${IMG['avatar_male.webp']}"><div><h4>${esc(p.username||p.display_name)}</h4><p class="small">${esc(p.rank)} • ⭐ ${Number(p.reputation||0).toLocaleString('tr-TR')} • ${esc(p.city)} / ${esc(p.district)} • ${onlineAgo(p.last_seen)}</p></div><div class="online-actions"><button class="btn gold" onclick="startPrivateChat('${p.id}','${esc(p.username||p.display_name)}')">MESAJ</button><button class="btn ghost" onclick="openOnlinePlayer('${p.id}')">PROFİL</button></div></div>`).join(''):`<div class="online-empty">Şu anda senden başka aktif oyuncu görünmüyor. Başka bir telefondan ikinci hesapla giriş yaptığında burada anında belirecek.</div>`}</div>
 </section>`;
}
async function setOnlineChatTab(tab){
 onlineChatChannel=tab;state.chatTab=tab;save();
 if(tab==='private'&&!onlineChatPeer){
   const peer=onlinePlayersCache.find(p=>p.id!==onlineSession?.user?.id);
   if(peer)onlineChatPeer={id:peer.id,name:peer.username||peer.display_name};
 }
 await loadOnlineChat(true);
}
function startPrivateChat(id,name){
 document.getElementById('onlinePlayerModal')?.remove();
 onlineChatPeer={id,name};
 onlineChatChannel='private';state.chatTab='private';currentPage='chat';save();
 loadOnlineChat(true);
}
async function loadOnlineChat(render=true){
 if(!onlineSession)return;
 try{
  const channel=onlineChatChannel||state.chatTab||'world';
  let args={p_channel:channel,p_family_id:null,p_peer_id:null,p_limit:80};
  if(channel==='family'){
    if(!onlineFamily){onlineChatCache=[];if(render&&currentPage==='chat')renderGame();return}
    args.p_family_id=onlineFamily.id;
  }
  if(channel==='private'){
    if(!onlineChatPeer){onlineChatCache=[];if(render&&currentPage==='chat')renderGame();return}
    args.p_peer_id=onlineChatPeer.id;
  }
  const {data,error}=await sb.rpc('recent_chat_messages',args);
  if(error)throw error;
  onlineChatCache=(Array.isArray(data)?data:[]).slice().reverse();
  if(render&&currentPage==='chat')renderGame();
 }catch(e){console.warn('chat load',e)}
}
function onlineChatView(){
 const active=onlineChatChannel||state.chatTab||'world';
 const peerOptions=onlinePlayersCache.filter(p=>p.id!==onlineSession?.user?.id);
 const title=active==='world'?'Dünya':active==='family'?'Aile':'Özel';
 return `<section class="card pad"><div class="section-head"><h2>Canlı Chat</h2><span class="server-badge"><span class="online-dot"></span>${title} kanalı</span></div>
 <div class="splash-actions"><button class="btn ${active==='world'?'gold':'ghost'}" onclick="setOnlineChatTab('world')">DÜNYA</button><button class="btn ${active==='family'?'gold':'ghost'}" onclick="setOnlineChatTab('family')">AİLE</button><button class="btn ${active==='private'?'gold':'ghost'}" onclick="setOnlineChatTab('private')">ÖZEL</button></div>
 ${active==='private'?`<div style="margin-top:10px"><select class="input" onchange="selectPrivatePeer(this.value)"><option value="">Oyuncu seç</option>${peerOptions.map(p=>`<option value="${p.id}" ${onlineChatPeer?.id===p.id?'selected':''}>${esc(p.username||p.display_name)} • ${esc(p.rank)}</option>`).join('')}</select></div>`:''}
 <div class="chat-online-box" id="onlineChatBox" style="margin-top:12px">
 ${onlineChatCache.length?onlineChatCache.map(m=>`<div class="chat-msg ${m.sender_id===onlineSession?.user?.id?'mine':''}"><div class="chat-head"><b>${esc(m.sender_name)}</b><span class="small">${new Date(m.created_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="chat-body">${esc(m.body)}</div></div>`).join(''):`<div class="online-empty">${active==='family'&&!onlineFamily?'Bir aileye katıldığında gerçek aile chat burada açılır.':active==='private'&&!onlineChatPeer?'Özel mesaj için bir online oyuncu seç.':'Bu kanalda henüz mesaj yok.'}</div>`}
 </div>
 <div style="display:flex;gap:8px;margin-top:10px"><input id="onlineChatInput" class="input" maxlength="500" placeholder="${active==='private'&&!onlineChatPeer?'Önce oyuncu seç':'Mesajını yaz...'}" onkeydown="if(event.key==='Enter')sendOnlineChat()" ${active==='family'&&!onlineFamily||active==='private'&&!onlineChatPeer?'disabled':''}><button class="btn gold" onclick="sendOnlineChat()" ${active==='family'&&!onlineFamily||active==='private'&&!onlineChatPeer?'disabled':''}>GÖNDER</button></div>
 <p class="small" style="margin-top:9px">Mesajlar sunucuda tutulur. Spam, taciz ve uygunsuz içerik şikâyet/engelleme sistemine tabidir.</p>
 </section>`;
}
async function selectPrivatePeer(id){
 const p=onlinePlayersCache.find(x=>x.id===id);
 onlineChatPeer=p?{id:p.id,name:p.username||p.display_name}:null;
 await loadOnlineChat(true);
}
async function sendOnlineChat(){
 const input=document.getElementById('onlineChatInput');if(!input||onlineBusy)return;
 const body=input.value.trim();if(!body)return;
 const active=onlineChatChannel||'world';
 let args={p_channel:active,p_body:body,p_family_id:null,p_recipient_id:null};
 if(active==='family'){if(!onlineFamily)return;args.p_family_id=onlineFamily.id}
 if(active==='private'){if(!onlineChatPeer)return;args.p_recipient_id=onlineChatPeer.id}
 onlineBusy=true;input.disabled=true;
 try{
  const {error}=await sb.rpc('send_chat_message',args);
  if(error)throw error;
  input.value='';
  await loadOnlineChat(true);
  setTimeout(()=>{const box=document.getElementById('onlineChatBox');if(box)box.scrollTop=box.scrollHeight},40);
 }catch(e){showInfo('Mesaj gönderilemedi',onlineErrText(e))}
 finally{onlineBusy=false;if(input)input.disabled=false}
}
async function startOnlineJob(id){
 if(onlineBusy)return;
 const j=JOBS.find(x=>x.id===id);if(!j)return;
 onlineBusy=true;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="jobModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[j.img]}')">${rainHTML(22)}</div><div class="modal-content"><div class="kicker">ONLINE GÖREV • ${esc(j.name)}</div><h2>Sunucu sonucu hesaplıyor...</h2><div class="meter"><i id="jobProg" style="width:12%"></i></div><p class="small" style="margin-top:10px">Para, enerji, itibar ve risk telefonunda değil KANUNSUZ sunucusunda hesaplanıyor.</p></div></div></div>`);
 let w=12;const anim=setInterval(()=>{w=Math.min(92,w+9);const el=document.getElementById('jobProg');if(el)el.style.width=w+'%'},120);
 try{
   const {data,error}=await sb.rpc('do_online_job',{p_job_id:id});
   if(error)throw error;
   await new Promise(r=>setTimeout(r,700));
   clearInterval(anim);document.getElementById('jobModal')?.remove();
   if(!data?.ok){
     const map={dead:'Karakterin ölü.',trial:'Mahkeme sürecindesin.',jail:'Hapistesin.',hospital:'Hastanedesin.',energy:'Enerjin yetmiyor.',reputation:'İtibarın yetersiz.'};
     showInfo('Görev açılamadı',map[data?.error]||'Sunucu bu göreve izin vermedi.');
     await syncOnlineState(true);return;
   }
   await syncOnlineState(false);
   const success=!!data.success;
   document.body.insertAdjacentHTML('beforeend',`<div class="modal ${success?'success':'police'}" id="resultModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[success?'result_success.webp':'result_fail.webp']||IMG[j.img]}')">${rainHTML(16)}</div><div class="modal-content">
   <div class="kicker">SUNUCU SONUCU</div><h2>${success?'İş tamamlandı.':'İş ters gitti.'}</h2>
   <div class="job-meta"><span class="chip">💵 ${fmt(Number(data.gain||0))}</span><span class="chip">⭐ +${Number(data.rep_gain||0)}</span>${data.police?'<span class="chip risk">🚨 Polis dikkatini çekti</span>':''}</div>
   <div class="modal-actions"><button class="btn gold" onclick="closeResult();renderGame()">DEVAM ET</button></div></div></div></div>`);
   renderGame();
 }catch(e){
   clearInterval(anim);document.getElementById('jobModal')?.remove();
   showInfo('Sunucu görevi başarısız',onlineErrText(e));
 }finally{onlineBusy=false}
}


