async function loadOnlinePvpTargets(render=true){
 if(!onlineSession)return;
 try{
  const {data,error}=await sb.rpc('online_pvp_targets');
  if(error)throw error;
  onlinePvpTargets=Array.isArray(data)?data:[];
  onlinePvpTargetsLoaded=true;
  if(render&&currentPage==='pvp')renderGame();
 }catch(e){
  console.warn('pvp targets',e);
  if(render)showInfo('PvP listesi alınamadı',onlineErrText(e));
 }
}

function onlinePvpView(){
 if(!onlinePvpTargetsLoaded){
   setTimeout(()=>loadOnlinePvpTargets(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Gerçek Oyuncu Çatışmaları</h2><span class="server-badge"><span class="online-dot"></span>Sunucu</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>Gerçek PvP hedefleri yükleniyor...</div></section>`;
 }
 const exLeft=Math.max(0,(state.executionCooldownUntil||0)-Date.now());
 const pvpLeft=Math.max(0,(state.pvpCooldownUntil||0)-Date.now());
 const exH=Math.floor(exLeft/3600000),exM=Math.floor((exLeft%3600000)/60000);
 const pvpM=Math.ceil(pvpLeft/60000);
 return `<section class="card pad"><div class="section-head"><h2>Gerçek Oyuncu Çatışmaları</h2><span class="server-badge"><span class="online-dot"></span>Server PvP</span></div>
 <div class="server-lock"><b>🔐 Sonuç sunucuda hesaplanır.</b> Güç, savunma, araç, ekipman, rütbe, itibar, polis riski, para kaybı ve bekleme süreleri telefonundaki JavaScript ile değiştirilemez.</div>
 <div class="image-card" style="margin:12px 0"><div class="pic" style="height:280px;background-image:url('${IMG['result_police.webp']}')">${rainHTML(20)}</div><div class="body"><h3>Saldırı ≠ İnfaz</h3>
 <p>Normal saldırı ölümcül değildir. İnfaz Emri kalıcı karakter ölümüne yol açabilir ve girişim başarılı olmasa bile 24 saatlik hakkını tüketir.</p>
 <div class="job-meta"><span class="chip">☠ Öldürme ${state.kills||0}</span><span class="chip">⚰ Ölüm ${state.deaths||0}</span><span class="chip">🚨 Tutuklanma ${state.arrests||0}</span>${pvpLeft>0?`<span class="chip">Normal saldırı: ~${pvpM} dk</span>`:''}${exLeft>0?`<span class="chip risk">İnfaz: ${exH} sa ${exM} dk</span>`:`<span class="chip">İnfaz Emri hazır</span>`}</div></div></div>
 <div class="section-head"><h2>Hedefler</h2><button class="btn ghost" onclick="loadOnlinePvpTargets(true)">↻ YENİLE</button></div>
 <div style="display:grid;gap:9px">${onlinePvpTargets.length?onlinePvpTargets.map(p=>{
   const sameCity=p.city===state.city;
   return `<div class="pvp-target"><div><h4>☠ ${esc(p.username)}</h4><p class="small">${esc(p.rank)} • ⭐ ${Number(p.reputation||0).toLocaleString('tr-TR')} • ${esc(p.family_name||'Bağımsız')}<br>${esc(p.city)} / ${esc(p.district)} • ❤️ ${p.hp} • Son görülme ${onlineAgo(p.last_seen)}</p></div>
   <div class="stack"><button class="btn" ${!sameCity||pvpLeft>0?'disabled':''} onclick="attackRealPlayer('${p.id}','${esc(p.username)}',false)">${!sameCity?'BAŞKA ŞEHİRDE':pvpLeft>0?'BEKLE':'SALDIR'}</button>
   <button class="btn red" ${!sameCity||exLeft>0?'disabled':''} onclick="confirmRealExecution('${p.id}','${esc(p.username)}')">${!sameCity?'BAŞKA ŞEHİRDE':exLeft>0?'24 SAAT KİLİTLİ':'İNFAZ EMRİ'}</button></div></div>`;
 }).join(''):`<div class="online-empty">Şu anda saldırıya uygun gerçek oyuncu yok.</div>`}</div>
 </section>`;
}

function confirmRealExecution(id,name){
 document.body.insertAdjacentHTML('beforeend',`<div class="modal police" id="executionConfirm"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG['result_police.webp']}')">${rainHTML(20)}</div><div class="modal-content">
 <div class="kicker">İNFAZ EMRİ</div><h2>${name}</h2>
 <div class="danger-note"><b>Bu gerçek bir online infaz girişimidir.</b> Başarılı olursa hedef karakter kalıcı olarak ölür. Başarısız olsa bile 24 saatlik infaz hakkın kapanır. Polis dosyası açılabilir.</div>
 <div class="modal-actions"><button class="btn red" onclick="document.getElementById('executionConfirm').remove();attackRealPlayer('${id}','${name}',true)">EMRİ VER</button><button class="btn ghost" onclick="document.getElementById('executionConfirm').remove()">VAZGEÇ</button></div>
 </div></div></div>`);
}

async function attackRealPlayer(id,name,isExecution){
 if(onlineBusy)return;
 onlineBusy=true;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="realPvpWait"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG['cin_intro_3.webp']}')">${rainHTML(25)}</div><div class="modal-content"><div class="kicker">${isExecution?'İNFAZ EMRİ':'SALDIRI'}</div><h2>Sunucu sonucu hesaplıyor...</h2><div class="meter"><i style="width:70%"></i></div><p class="small">${name} için bütün güç ve risk hesapları server tarafında yapılıyor.</p></div></div></div>`);
 try{
   const fn=isExecution?'execute_online_player':'attack_online_player';
   const {data,error}=await sb.rpc(fn,{p_target:id});
   if(error)throw error;
   document.getElementById('realPvpWait')?.remove();
   if(!data?.ok){
     showInfo(isExecution?'İnfaz yapılamadı':'Saldırı yapılamadı',serverErrorMessage(data,isExecution?'İnfaz':'Saldırı'));
     await syncOnlineState(true);
     return;
   }
   await Promise.all([syncOnlineState(false),loadOnlinePvpTargets(false)]);
   if(data.police_caught)await loadOnlineCurrentCase(false);
   currentPage=data.police_caught?'court':'pvp';
   renderGame();
   const success=isExecution?!!data.killed:!!data.win;
   const heading=isExecution?(success?'Hedef öldü.':'İnfaz başarısız.'):(success?'Rakip yaralandı.':'Saldırı ters gitti.');
   document.body.insertAdjacentHTML('beforeend',`<div class="modal ${success?'success':'police'}" id="resultModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[success?'result_success.webp':'result_police.webp']}')">${rainHTML(18)}</div><div class="modal-content">
   <div class="kicker">${isExecution?'ONLINE İNFAZ SONUCU':'ONLINE SALDIRI SONUCU'}</div><h2>${heading}</h2>
   <p class="small">Hedef: ${name}</p>
   <div class="job-meta"><span class="chip">💵 Ganimet ${fmt(Number(data.loot||0))}</span><span class="chip">⭐ ${Number(data.rep_delta||0)>=0?'+':''}${Number(data.rep_delta||0)} itibar</span><span class="chip">🚨 Polis riski %${Number(data.police_risk||0)}</span>${data.police_caught?'<span class="chip risk">⚖ Yakalandın, dosya açıldı</span>':''}</div>
   <div class="modal-actions"><button class="btn gold" onclick="closeResult();${data.police_caught?"currentPage='court';renderGame()":"currentPage='pvp';renderGame()"}">DEVAM ET</button></div>
   </div></div></div>`);
 }catch(e){
   document.getElementById('realPvpWait')?.remove();
   showInfo('Sunucu hatası',onlineErrText(e));
 }finally{onlineBusy=false}
}

async function loadOnlineFamilySetup(render=true){
 if(!onlineSession)return;
 try{
   const {data,error}=await sb.rpc('my_family_setup');
   if(error)throw error;
   onlineFamilySetup=data||{};
   onlineFamilySetupLoaded=true;
   const f=data?.family||null;
   onlineFamily=f?{id:f.id,name:f.name,role:f.role}:null;
   state.family=f?.name||null;state.familyRole=f?.role||null;state.properties=(data?.properties||[]).map(x=>x.name);
   if(render&&currentPage==='families')renderGame();
 }catch(e){
   console.warn('family setup',e);
   if(render)showInfo('Aile bilgisi alınamadı',onlineErrText(e));
 }
}

function familyRankReady(){
 return ['Kabadayı','Reis','Baba','Patron','Konsey Başı'].includes(state.rank);
}

