 <div class="cards2">${lawyers.map(l=>`<article class="image-card"><div class="body"><h3>⚖ ${l.name}</h3><div class="job-meta"><span class="chip">Beraat tabanı %${l.chance}</span><span class="chip">${l.cost?fmt(l.cost):'Ücretsiz'}</span>${l.reduce?`<span class="chip">Ceza -${l.reduce} gün</span>`:''}</div><button class="btn ${l.id==='famous'||l.id==='team'?'gold':''}" onclick="resolveRealCourt('${l.id}')">BU AVUKATLA ÇIK</button></div></article>`).join('')}</div>
