async function resolveRealCourt(lawyerId){
 if(onlineBusy)return;
 onlineBusy=true;
 try{
  const {data,error}=await sb.rpc('resolve_online_case',{p_lawyer_id:lawyerId});
  if(error)throw error;
  if(!data?.ok){showInfo('Mahkeme sonuçlanmadı',serverErrorMessage(data,'Mahkeme'));return}
  onlineCurrentCase=null;onlineCurrentCaseLoaded=false;
  await syncOnlineState(false);
  currentPage=data.acquitted?'home':'jail';renderGame();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal ${data.acquitted?'success':'police'}" id="resultModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG['result_police.webp']}')">${rainHTML(15)}</div><div class="modal-content"><div class="kicker">SUNUCU MAHKEME KARARI</div><h2>${data.acquitted?'BERAAT':'MAHKÛMİYET'}</h2><p class="small">${esc(data.charge)} • ${esc(data.lawyer)} • Beraat hesabı %${Number(data.chance||0)}</p>${data.acquitted?'<p>Dosya kapandı. Şehre dönebilirsin.</p>':`<p><b>${Number(data.days||0)} gerçek gün</b> hapis cezası verildi.</p>`}<div class="modal-actions"><button class="btn gold" onclick="closeResult();renderGame()">DEVAM</button></div></div></div></div>`);
 }catch(e){showInfo('Mahkeme hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}


async function loadOnlineTerritory(render=true){
 if(!onlineSession)return;
 try{
   const [mapRes,warRes]=await Promise.all([
     sb.rpc('online_territory_map'),
     sb.rpc('my_territory_war_state')
   ]);
   if(mapRes.error)throw mapRes.error;
   if(warRes.error)throw warRes.error;
   onlineTerritoryMap=Array.isArray(mapRes.data)?mapRes.data:[];
   onlineWarState=warRes.data||{state:null,recent:[]};
   onlineTerritoryLoaded=true;onlineWarLoaded=true;
   if(render&&currentPage==='territories')renderGame();
 }catch(e){
   console.warn('territory load',e);
   if(render)showInfo('Bölge haritası alınamadı',onlineErrText(e));
 }
}

function familyTerritoryEntries(districtId){
 return onlineTerritoryMap.filter(x=>x.district_id===districtId).sort((a,b)=>Number(b.share||0)-Number(a.share||0));
}
function myTerritoryEntry(districtId){
 const fid=onlineFamilySetup?.family?.id;
 return familyTerritoryEntries(districtId).find(x=>x.entity_type==='family'&&x.entity_id===fid)||null;
}
function territoryWarCooldownMs(){
 const until=onlineWarState?.state?.cooldown_until;
 return until?Math.max(0,Date.parse(until)-Date.now()):0;
}

async function buyOnlineFamilyBusiness(businessId,districtId){
 if(onlineBusy)return;
 const b=ONLINE_FAMILY_BUSINESSES.find(x=>x.id===businessId);
 if(!b)return;
 if(!confirm(`${b.name} şubesi ${districtNameOnline(districtId)} semtinde ${fmt(b.price)} karşılığında Aile Kasasından açılsın mı?`))return;
 onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('buy_family_business_online',{p_business:businessId,p_district:districtId});
   if(error)throw error;
   if(!data?.ok){showInfo('Şube açılamadı',serverErrorMessage(data,'İşletme'));return}
   await Promise.all([loadOnlineFamilySetup(false),loadOnlineTerritory(false)]);
   renderGame();
   showInfo('Yeni şube açıldı',`${data.business} • ${districtNameOnline(data.district)} • ${fmt(Number(data.price||0))}. Aile seviyesi: ${Number(data.level||1)}`);
 }catch(e){showInfo('İşletme hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}

