function onlineFamilyEconomyBlock(){
 const s=onlineFamilySetup||{},f=s.family||null;
 if(!f)return '';
 const businesses=s.businesses||[];
 const role=f.role||'Üye';
 const canBuy=role==='Aile Lideri';
 const canClaim=['Aile Lideri','Kasa Sorumlusu','Sağ Kol'].includes(role);
 const hourly=businesses.reduce((n,b)=>n+Number(b.income_per_hour||0),0);
 const influence=businesses.reduce((n,b)=>n+Number(b.influence||0),0);
 return `<div class="section-head" style="margin-top:18px"><h2>Aile Ekonomisi</h2><span class="server-badge"><span class="online-dot"></span>Gerçek Aile Kasası</span></div>
 <div class="biz-summary"><div class="quick"><b>${fmt(Number(f.treasury||0))}</b><small>Aile Kasası</small></div><div class="quick"><b>${businesses.length}</b><small>Toplam Şube</small></div><div class="quick"><b>${fmt(hourly)}/sa</b><small>Ham Gelir</small></div><div class="quick"><b>+${influence}</b><small>Şube Nüfuzu</small></div></div>
 <div class="server-lock"><b>Gelir saatlik ve sunucudadır.</b> %35 semt payında o semtteki şubeler +%10, %50 ve üzerinde +%20 gelir üretir. Cihaz saatini değiştirmek gelir oluşturmaz.</div>
 <div class="splash-actions" style="margin-top:10px"><button class="btn gold" ${canClaim?'':'disabled'} onclick="claimOnlineFamilyIncome()">💰 BİRİKEN GELİRİ KASAYA AL</button><button class="btn ghost" onclick="currentPage='territories';loadOnlineTerritory(true)">🗺 ORTAK HARİTAYI AÇ</button></div>
 <div class="section-head" style="margin-top:16px"><h2>Yeni Şube Aç</h2><span class="badge">${canBuy?'Aile Lideri yetkili':'Yalnız Aile Lideri'}</span></div>
 <div class="biz-catalog">${ONLINE_FAMILY_BUSINESSES.map(b=>{
   const levelOk=Number(f.level||1)>=b.level, cashOk=Number(f.treasury||0)>=b.price;
   return `<div class="biz-online-card"><div class="kicker">SEVİYE ${b.level}+</div><h3>${esc(b.name)}</h3><p class="small">Saatlik ${fmt(b.income)} • Prestij +${b.prestige} • Semt nüfuzu +${b.influence}</p><div class="job-meta"><span class="chip">${fmt(b.price)}</span>${!levelOk?`<span class="chip risk">Aile seviyesi ${b.level} gerekli</span>`:''}${!cashOk?`<span class="chip risk">Kasa yetersiz</span>`:''}</div><button class="btn ${canBuy&&levelOk&&cashOk?'gold':''}" ${canBuy&&levelOk&&cashOk?'':'disabled'} onclick="openOnlineBusinessModal('${b.id}')">ŞUBE AÇ</button></div>`;
 }).join('')}</div>`;
}

function onlineTerritoriesView(){
 if(!onlineTerritoryLoaded||!onlineWarLoaded){
   setTimeout(()=>loadOnlineTerritory(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Canlı İstanbul Haritası</h2><span class="server-badge"><span class="online-dot"></span>Ortak dünya</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>Gerçek semt yüzdeleri sunucudan yükleniyor...</div></section>`;
 }
 const f=onlineFamilySetup?.family||null;
 const isLeader=f?.role==='Aile Lideri';
 const cd=territoryWarCooldownMs();
 const cdH=Math.floor(cd/3600000),cdM=Math.floor((cd%3600000)/60000);
 const recent=onlineWarState?.recent||[];
 return `<section class="card pad"><div class="section-head"><h2>Canlı İstanbul Haritası</h2><span class="server-badge"><span class="online-dot"></span>Tek ortak dünya</span></div>
 <div class="image-card" style="margin-bottom:12px"><div class="pic" style="height:300px;background-image:url('${IMG['istanbul.webp']}')">${rainHTML(16)}</div><div class="body"><h3>Bu yüzdeler artık herkeste aynı.</h3><p>İşletme açıldığında semt payı sunucuda değişir. %12 aile payı savaş açma eşiğidir. %35 güçlü konum, %50 hâkimiyettir. Savaş bütçesi 500.000 TL Aile Kasasından çıkar.</p>${cd>0?`<div class="badge">Yeni savaş: ${cdH} sa ${cdM} dk</div>`:''}</div></div>
 <div class="cards2">${DISTRICTS.map(d=>{
   const entries=familyTerritoryEntries(d.id);
   const own=myTerritoryEntry(d.id);
   const ownShare=Number(own?.share||0);
   const status=ownShare>=50?'👑 HÂKİM':ownShare>=35?'🔥 GÜÇLÜ':ownShare>=12?'⚔ RAKİP':'• ZAYIF';
   const canWar=!!f&&isLeader&&ownShare>=12&&cd<=0&&Number(f.treasury||0)>=500000;
   return `<article class="territory-online-card"><div class="pic" style="height:150px;background-image:url('${IMG[d.img]}')"><div class="city-name">${d.name}</div></div>
   <div class="territory-online-head"><div><b>${entries[0]?esc(entries[0].entity_name):'Bilinmiyor'}</b><div class="small">Lider • %${Number(entries[0]?.share||0).toFixed(1)}</div></div><span class="badge">${status}</span></div>
   <div class="territory-online-list">${entries.slice(0,5).map(e=>`<div class="territory-row ${e.entity_id===f?.id?'mine':''}"><div><b>${e.entity_id===f?.id?'★ ':''}${esc(e.entity_name)}</b><div class="small">${e.entity_type==='incumbent'?'Yerleşik yapı':'Oyuncu ailesi'} • Nüfuz ${Number(e.influence||0)}</div><div class="territory-bar"><i style="width:${Math.min(100,Number(e.share||0))}%"></i></div></div><b>%${Number(e.share||0).toFixed(1)}</b></div>`).join('')}</div>
   <div style="padding:0 14px 14px"><button class="btn ${canWar?'red':''}" ${canWar?'':'disabled'} onclick="openRealTerritoryWar('${d.id}')">${!f?'AİLE GEREKLİ':!isLeader?'LİDER GEREKLİ':ownShare<12?'ÖNCE %12 NÜFUZ':cd>0?'SAVAŞ BEKLEMEDE':Number(f.treasury||0)<500000?'KASA 500.000 TL':'BÖLGE SAVAŞI'}</button></div>
   </article>`;
 }).join('')}</div>
 <div class="section-head" style="margin-top:18px"><h2>Son Aile Savaşların</h2><span class="badge">${recent.length}</span></div>
 ${recent.length?`<div class="war-history">${recent.map(w=>`<div class="list-row ${w.result==='win'?'win':'loss'}"><div><h4>${districtNameOnline(w.district_id)} • ${esc(w.defender_name)}</h4><p>${new Date(w.created_at).toLocaleString('tr-TR')}</p></div><b>${w.result==='win'?'✅ +':'❌ '}${Number(w.influence_delta||0)}</b></div>`).join('')}</div>`:`<div class="online-empty">Henüz sunucuda bölge savaşı kaydın yok.</div>`}
 </section>`;
}

function openRealTerritoryWar(districtId){
 const f=onlineFamilySetup?.family;
 if(!f||f.role!=='Aile Lideri')return;
 const entries=familyTerritoryEntries(districtId);
 const own=myTerritoryEntry(districtId);
 const ownShare=Number(own?.share||0);
 if(ownShare<12){showInfo('Nüfuz yetersiz','Gerçek aile payın en az %12 olmalı.');return}
 const rivals=entries.filter(e=>e.entity_id!==f.id);
 const dName=districtNameOnline(districtId);
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="realWarModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[districtImgOnline(districtId)]}')">${rainHTML(18)}</div><div class="modal-content">
 <div class="kicker">GERÇEK BÖLGE SAVAŞI • ${dName}</div><h2>Rakibini seç.</h2>
 <p class="small">Aile payın %${ownShare.toFixed(1)}. Savaş bütçesi 500.000 TL Aile Kasasından çıkar ve sonuç sunucuda hesaplanır. Savaş sonrası 6 saat yeni savaş açılamaz.</p>
 <div class="list">${rivals.map(r=>`<div class="list-row"><div><h4>${esc(r.entity_name)}</h4><p>${r.entity_type==='incumbent'?'Yerleşik yapı':'Oyuncu ailesi'} • %${Number(r.share||0).toFixed(1)}</p></div><button class="btn red" onclick="document.getElementById('realWarModal').remove();launchRealTerritoryWar('${districtId}',${r.entity_id?`'${r.entity_id}'`:'null'},'${esc(r.entity_name).replace(/'/g,"\\'")}')">SAVAŞ</button></div>`).join('')}</div>
 <div class="modal-actions"><button class="btn ghost" onclick="document.getElementById('realWarModal').remove()">VAZGEÇ</button></div>
 </div></div></div>`);
}

async function launchRealTerritoryWar(districtId,defenderId,defenderName){
 if(onlineBusy)return;
 onlineBusy=true;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="warWait"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[districtImgOnline(districtId)]}')">${rainHTML(24)}</div><div class="modal-content"><div class="kicker">BÖLGE SAVAŞI</div><h2>Sunucu güçleri hesaplıyor...</h2><div class="meter"><i style="width:75%"></i></div><p class="small">${districtNameOnline(districtId)} • Rakip: ${esc(defenderName)}</p></div></div></div>`);
 try{
   const {data,error}=await sb.rpc('declare_online_territory_war',{p_district:districtId,p_defender_family:defenderId||null});
   if(error)throw error;
   document.getElementById('warWait')?.remove();
   if(!data?.ok){showInfo('Savaş açılamadı',serverErrorMessage(data,'Bölge savaşı'));await loadOnlineTerritory(false);return}
   await Promise.all([loadOnlineFamilySetup(false),loadOnlineTerritory(false)]);
   renderGame();
   document.body.insertAdjacentHTML('beforeend',`<div class="modal ${data.won?'success':'police'}" id="resultModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[districtImgOnline(districtId)]}')">${rainHTML(18)}</div><div class="modal-content"><div class="kicker">${districtNameOnline(districtId)} • SERVER SAVAŞI</div><h2>${data.won?'BÖLGE SAVAŞI KAZANILDI':'BÖLGE SAVAŞI KAYBEDİLDİ'}</h2><p class="small">Rakip: ${esc(data.defender||defenderName)} • Nüfuz ${Number(data.delta||0)>=0?'+':''}${Number(data.delta||0)} • Yeni pay yaklaşık %${Number(data.share||0).toFixed(1)} • Maliyet ${fmt(Number(data.cost||500000))}</p><div class="modal-actions"><button class="btn gold" onclick="closeResult();currentPage='territories';renderGame()">HARİTAYA DÖN</button></div></div></div></div>`);
 }catch(e){
   document.getElementById('warWait')?.remove();
   showInfo('Savaş hatası',onlineErrText(e));
 }finally{onlineBusy=false}
}


async function loadOnlineSocial(render=true){
 if(!onlineSession)return;
 try{
   const [stateRes,candRes]=await Promise.all([
     sb.rpc('my_relationship_state'),
     sb.rpc('relationship_candidates')
   ]);
   if(stateRes.error)throw stateRes.error;
   if(candRes.error)throw candRes.error;
   onlineRelationshipState=stateRes.data||{relationship:null,incoming:[],outgoing:[],wedding_invites:[],venues:[]};
   onlineRelationshipCandidates=Array.isArray(candRes.data)?candRes.data:[];
   onlineRelationshipLoaded=true;onlineRelationshipCandidatesLoaded=true;
   const rel=onlineRelationshipState.relationship;
   state.spouse=rel?.status==='married'?rel.partner_name:null;
   state.engagedTo=rel?.status==='engaged'?rel.partner_name:null;
   state.relationship=Number(rel?.relationship_score||0);
   state.weddingVenue=rel?.venue_id||null;
   save();
   if(render&&currentPage==='social')renderGame();
 }catch(e){
   console.warn('social load',e);
   if(render)showInfo('Sosyal sistem yüklenemedi',onlineErrText(e));
 }
}

async function loadOnlinePremium(render=true){
 if(!onlineSession)return;
 try{
   const [premiumRes,candidateRes]=await Promise.all([
     sb.rpc('my_premium_state'),
     sb.rpc('premium_gift_candidates')
   ]);
   if(premiumRes.error)throw premiumRes.error;
   if(candidateRes.error)throw candidateRes.error;
   onlinePremiumState=premiumRes.data||{};
   onlineGiftCandidates=Array.isArray(candidateRes.data)?candidateRes.data:[];
   onlinePremiumLoaded=true;onlineGiftCandidatesLoaded=true;
   state.credits=Number(onlinePremiumState.credits||0);
   save();
   if(render&&currentPage==='shop')renderGame();
 }catch(e){
   console.warn('premium load',e);
   if(render)showInfo('Premium sistem yüklenemedi',onlineErrText(e));
 }
}

function relationshipTimeLeft(ts){
 if(!ts)return '';
 const ms=Date.parse(ts)-Date.now();
 if(ms<=0)return 'Başlamak üzere';
 const d=Math.floor(ms/86400000),h=Math.floor((ms%86400000)/3600000),m=Math.floor((ms%3600000)/60000);
 return `${d?d+' gün ':''}${h} sa ${m} dk`;
}

