   setTimeout(()=>loadOnlineSocial(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Gerçek Sosyal Hayat</h2><span class="server-badge"><span class="online-dot"></span>Online</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>İlişkiler ve gerçek oyuncular yükleniyor...</div></section>`;
