async function endRealRelationship(id,status){
 if(onlineBusy)return;
 const msg=status==='married'?'Bu evliliği sonlandırmak istediğine emin misin?':'Nişanı bitirmek istediğine emin misin?';
 if(!confirm(msg))return;
 onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('end_online_relationship',{p_relationship:id});
   if(error)throw error;
   if(!data?.ok){showInfo('İlişki sonlandırılamadı','Sunucu işlemi reddetti.');return}
   await loadOnlineSocial(false);renderGame();
   showInfo(data.status==='divorced'?'Boşanma kaydedildi':'Nişan sona erdi','İlişki durumu sunucuda güncellendi.');
 }catch(e){showInfo('Sunucu hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}

