function councilMotionName(type){
 return ({city_ceasefire:'Şehir Ateşkesi',night_economy:'Gece Ekonomisi',general_calm:'Genel Sükûnet'})[type]||type;
}
function councilEffectText(e){
 if(e.effect_key==='city_ceasefire')return '🕊 Şehir Ateşkesi';
 if(e.effect_key==='night_economy')return '💰 Gece Ekonomisi +%15';
 return esc(e.effect_key);
}
function councilEligibilityBlock(e){
 if(!e)return '';
 const req=e.requirements||{};
 const rows=[
   ['Rütbe','Patron',e.rank==='Patron'||e.rank==='Konsey Başı'],
   ['İtibar','300.000',Number(e.reputation||0)>=Number(req.reputation||300000)],
   ['Aile görevi','Aile Lideri',e.role==='Aile Lideri'],
   ['Aile seviyesi','5',Number(e.family_level||0)>=Number(req.family_level||5)],
   ['Grup operasyonu','15 galibiyet',Number(e.group_ops_won||0)>=Number(req.group_ops_won||15)],
   ['Mülk','3',Number(e.properties||0)>=Number(req.properties||3)],
   ['Servet','10.000.000 TL',Number(e.wealth||0)>=Number(req.wealth||10000000)],
   ['Güçlü semt','2 adet %35+',Number(e.strong_districts||0)>=Number(req.strong_districts||2)]
 ];
 return `<div class="council-card"><div class="section-head"><h3>Konsey Uygunluğu</h3><span class="badge">${e.eligible?'HAZIR':'EKSİK ŞART VAR'}</span></div>${rows.map(r=>`<div class="eligibility-line"><span>${r[0]} <span class="small">• ${r[1]}</span></span><b>${r[2]?'✅':'❌'}</b></div>`).join('')}<div class="quick-grid" style="margin-top:10px"><div class="quick"><b>${Number(e.score||0).toFixed(1)}</b><small>Konsey skoru</small></div><div class="quick"><b>${Number(e.strong_districts||0)}</b><small>Güçlü semt</small></div></div>${e.eligible?`<button class="btn gold full" style="margin-top:10px" onclick="applyRealCouncil()">SİYAH KONSEY'E BAŞVUR</button>`:''}</div>`;
}
function onlineCouncilView(){
 if(!onlineCouncilLoaded){
   setTimeout(()=>loadOnlineCouncil(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Siyah Konsey</h2><span class="server-badge"><span class="online-dot"></span>7 sandalye</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>Mavi Kapının arkasındaki masa açılıyor...</div></section>`;
 }
 const c=onlineCouncilState||{},seats=c.seats||[],head=c.head||null,election=c.head_election||null,motion=c.motion||null,effects=c.effects||[],cands=c.candidates||[],recent=c.recent||[];
 const occupied=Number(c.occupied||0);
 const headLeft=head?.term_until?Math.max(0,Date.parse(head.term_until)-Date.now()):0;
 const headD=Math.floor(headLeft/86400000),headH=Math.floor((headLeft%86400000)/3600000);
 return `<section class="card pad"><div class="section-head"><h2>Siyah Konsey</h2><span class="badge">7 sandalye • ${occupied} dolu</span></div>
 <div class="council-table"><div class="council-table-bg" style="background-image:url('${IMG['cin_intro_4.webp']}')"></div>${rainHTML(12)}<div class="council-table-copy"><div class="kicker">MAVİ KAPININ ARKASI</div><h2 style="font-family:Georgia,serif;margin:5px 0">7 sandalye. Artık boşluğun bir anlamı var.</h2><p class="small">Bir aile yalnızca bir sandalye taşıyabilir. Konsey Başı satın alınamaz; yedi sandalyenin siyasi desteğiyle gelir.</p></div></div>
 <div class="council-seats">${seats.map(s=>`<div class="council-seat ${s.holder_id?'occupied':''} ${head?.holder_id===s.holder_id?'head':''}"><div style="font-size:22px">${head?.holder_id===s.holder_id?'👑':s.holder_id?'♜':'◇'}</div><b>${s.holder_id?esc(s.holder_name):'BOŞ'}</b><small>${s.holder_id?esc(s.family_name||'Ailesiz'):`${Number(s.seat_no)}. sandalye`}</small></div>`).join('')}</div>
 ${effects.length?`<div style="margin-top:10px">${effects.map(e=>`<span class="council-effect">${councilEffectText(e)} • ${notificationAgo(e.active_until).includes('önce')?'aktif':new Date(e.active_until).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})+' kadar'}</span>`).join('')}</div>`:''}

 <div class="council-grid">
 <div>
 ${c.is_member?`<div class="council-card"><div class="section-head"><h3>Sen Konseydesin</h3><span class="badge">♜ Sandalye sahibi</span></div><p class="small">Aile liderliğini veya Patron seviyesini kaybedersen sandalyen otomatik boşalır. Karakter ölümü de üyeliği bitirir.</p>${head?.holder_id?`<div class="kicker">KONSEY BAŞI</div><h2>${esc(head.holder_name||'')}</h2><p class="small">${esc(head.family_name||'')} • Görev süresi ${head?.term_until?new Date(head.term_until).toLocaleString('tr-TR'):'-'}</p><div class="term-countdown">${headLeft>0?`${headD} gün ${headH} saat`:'Süre doldu'}</div>`:`<p>Henüz Konsey Başı yok.</p>`}
 ${!head?.holder_id&&!election&&occupied>=3?`<button class="btn gold" onclick="startRealCouncilHeadElection()">KONSEY BAŞI SEÇİMİNİ BAŞLAT</button>`:''}</div>`:councilEligibilityBlock(c.eligibility)}

 ${c.my_candidate?`<div class="council-card" style="margin-top:10px"><div class="kicker">ADAYLIK DOSYAN</div><h3>Konsey oylaması sürüyor.</h3><div class="job-meta"><span class="chip">✅ ${Number(c.my_candidate.yes_votes||0)} evet</span><span class="chip">❌ ${Number(c.my_candidate.no_votes||0)} hayır</span><span class="chip">Gerekli ${Number(c.majority_needed||1)}</span></div></div>`:''}

 ${c.is_member&&cands.length?`<div class="council-card" style="margin-top:10px"><div class="section-head"><h3>Konsey Adayları</h3><span class="badge">${cands.length}</span></div>${cands.map(x=>`<div class="candidate-card"><h4>${esc(x.applicant_name)} • ${esc(x.family_name)}</h4><p class="small">${esc(x.rank)} • ⭐ ${Number(x.reputation||0).toLocaleString('tr-TR')} • Konsey skoru ${Number(x.score||0).toFixed(1)}</p><div class="job-meta"><span class="chip">✅ ${Number(x.yes_votes||0)}</span><span class="chip">❌ ${Number(x.no_votes||0)}</span></div><div class="splash-actions"><button class="btn gold" onclick="voteRealCouncilCandidate('${x.id}',true)">KABUL</button><button class="btn red" onclick="voteRealCouncilCandidate('${x.id}',false)">RED</button></div></div>`).join('')}</div>`:''}
 </div>

 <div>
 ${election?`<div class="council-card"><div class="kicker">24 SAATLİK SEÇİM</div><h3>Konsey Başı seçiliyor.</h3><p class="small">Görev süresi 7 gündür. Kazanmak için dolu sandalyelerin en az %67 desteği, minimum 3 oy gerekir.</p>${(election.candidates||[]).map(x=>`<div class="candidate-card"><div class="section-head"><h4>${esc(x.name)}</h4><b>${Number(x.votes||0)} oy</b></div><p class="small">${esc(x.family||'')}</p>${c.is_member?`<button class="btn gold" onclick="voteRealCouncilHead('${x.id}')">OY VER</button>`:''}</div>`).join('')}</div>`:''}

 ${c.is_head?`<div class="council-card ${election?'':' '}" style="margin-top:${election?'10':'0'}px"><div class="kicker">KONSEY BAŞI YETKİSİ</div><h3>Şehir kararı öner.</h3><p class="small">Aynı anda tek karar oylanabilir. Yeni karar önerme için 24 saat bekleme uygulanır.</p><div class="splash-actions"><button class="btn" onclick="proposeRealCouncilMotion('city_ceasefire')">🕊 6 SAAT ATEŞKES</button><button class="btn" onclick="proposeRealCouncilMotion('night_economy')">💰 GECE EKONOMİSİ</button><button class="btn" onclick="proposeRealCouncilMotion('general_calm')">🚨 GENEL SÜKÛNET</button></div></div>`:''}

 ${motion?`<div class="motion-card" style="margin-top:10px"><div class="kicker">AKTİF KONSEY OYLAMASI</div><h3>${councilMotionName(motion.motion_type)}</h3><div class="job-meta"><span class="chip">✅ ${Number(motion.yes_votes||0)}</span><span class="chip">❌ ${Number(motion.no_votes||0)}</span><span class="chip">Gerekli ${Number(c.majority_needed||1)}</span></div>${c.is_member?`<div class="splash-actions"><button class="btn gold" onclick="voteRealCouncilMotion('${motion.id}',true)">EVET</button><button class="btn red" onclick="voteRealCouncilMotion('${motion.id}',false)">HAYIR</button></div>`:''}</div>`:''}

 <div class="council-card" style="margin-top:10px"><div class="section-head"><h3>Konsey Kayıtları</h3><span class="badge">${recent.length}</span></div>${recent.length?recent.slice(0,10).map(r=>`<div class="list-row"><div><h4>♜ ${esc(r.body)}</h4><p>${new Date(r.created_at).toLocaleString('tr-TR')}</p></div></div>`).join(''):'<div class="online-empty">Konsey henüz şehirde iz bırakmadı.</div>'}</div>
 </div>
 </div>
 <div class="server-lock" style="margin-top:12px"><b>Konsey Başı bir sezonluk unvan değil, 7 günlük aktif görevdir.</b> Süre bittiğinde rütbe tekrar Patron olur ve yeni seçim açılabilir. Böylece unvan kalıcı olarak tek oyuncuda kilitlenmez.</div>
 </section>`;
}

async function applyRealCouncil(){
 if(onlineBusy)return;
 onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('apply_for_council');
   if(error)throw error;
   if(!data?.ok){
     const extra=data?.eligibility?` Konsey skoru: ${Number(data.eligibility.score||0).toFixed(1)}.`:'';
     showInfo('Konsey başvurusu reddedildi',serverErrorMessage(data,'Konsey')+extra);return;
   }
   await Promise.all([loadOnlineCouncil(false),loadOnlineNotifications(false),loadOnlineWorldNews(false)]);
   renderGame();
   showInfo(data.seated?'SANDALYE SENİN':'ADAYLIK DOSYAN AÇILDI',data.seated?`${Number(data.seat_no)}. sandalyeye oturdun. İlk üç sandalye kurucu aşamasında doğrudan dolabilir.`:'Mevcut Konsey üyeleri adaylığını oylayacak.');
 }catch(e){showInfo('Konsey hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}
async function voteRealCouncilCandidate(id,approve){
 if(onlineBusy)return;onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('vote_council_candidate',{p_candidate:id,p_approve:approve});
   if(error)throw error;
   if(!data?.ok){showInfo('Oy kullanılamadı',serverErrorMessage(data,'Konsey oyu'));return}
   await loadOnlineCouncil(false);renderGame();
   showInfo('Konsey oyu kaydedildi',data.resolved?`Adaylık ${data.resolved==='accepted'?'kabul edildi':'reddedildi'}.`:`Evet ${Number(data.yes||0)} • Hayır ${Number(data.no||0)} • Gerekli ${Number(data.needed||0)}`);
 }catch(e){showInfo('Konsey hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}
async function startRealCouncilHeadElection(){
 if(onlineBusy)return;onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('start_council_head_election');
   if(error)throw error;
   if(!data?.ok){showInfo('Seçim açılamadı',serverErrorMessage(data,'Konsey Başı seçimi'));return}
   await loadOnlineCouncil(false);renderGame();
   showInfo('Konsey Başı seçimi başladı','24 saatlik oylama açıldı. Konsey üyeleri yedi sandalye arasından seçim yapacak.');
 }catch(e){showInfo('Seçim hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}
async function voteRealCouncilHead(id){
 if(onlineBusy)return;onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('vote_council_head',{p_candidate:id});
   if(error)throw error;
   if(!data?.ok){showInfo('Oy kullanılamadı',serverErrorMessage(data,'Konsey Başı oyu'));return}
   await Promise.all([loadOnlineCouncil(false),syncOnlineState(false)]);
   renderGame();
   showInfo(data.winner_id?'YENİ KONSEY BAŞI':'Oyun kaydedildi',data.winner_id?'Gerekli destek sağlandı. Kazanan oyuncu 7 günlüğüne Konsey Başı oldu.':`${Number(data.votes||0)} oy • Gerekli ${Number(data.needed||0)}`);
 }catch(e){showInfo('Seçim hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}
async function proposeRealCouncilMotion(type){
 if(onlineBusy)return;onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('propose_council_motion',{p_motion_type:type});
   if(error)throw error;
   if(!data?.ok){showInfo('Karar açılamadı',serverErrorMessage(data,'Konsey kararı'));return}
   await loadOnlineCouncil(false);renderGame();
   showInfo('Konsey oylaması açıldı',councilMotionName(type)+' kararı 12 saat süreyle oylamada.');
 }catch(e){showInfo('Konsey hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}
async function voteRealCouncilMotion(id,approve){
 if(onlineBusy)return;onlineBusy=true;
 try{
   const {data,error}=await sb.rpc('vote_council_motion',{p_motion:id,p_approve:approve});
   if(error)throw error;
   if(!data?.ok){showInfo('Karar oylanamadı',serverErrorMessage(data,'Konsey kararı'));return}
   await Promise.all([loadOnlineCouncil(false),loadOnlineTerritory(false),loadOnlineFamilySetup(false),syncOnlineState(false)]);
   renderGame();
   showInfo('Konsey oyu kaydedildi',data.status==='passed'?'Karar geçti ve şehirde uygulanmaya başladı.':data.status==='rejected'?'Karar reddedildi.':`Evet ${Number(data.yes||0)} • Hayır ${Number(data.no||0)} • Gerekli ${Number(data.needed||0)}`);
 }catch(e){showInfo('Konsey hatası',onlineErrText(e))}
 finally{onlineBusy=false}
}


async function loadOnlineGarage(render=true){
 if(!onlineSession)return;
 try{
   const {data,error}=await sb.rpc('my_garage_inventory');
   if(error)throw error;
   onlineGarageState=data||{};
   onlineGarageLoaded=true;
   const active=(data?.vehicles||[]).find(v=>v.active);
   state.car=active?.name||null;
   if(render&&currentPage==='garage')renderGame();
 }catch(e){console.warn('garage',e);if(render)showInfo('Garaj yüklenemedi',onlineErrText(e))}
}
function onlineGarageView(){
 if(!onlineGarageLoaded){
   setTimeout(()=>loadOnlineGarage(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Gerçek Garaj</h2><span class="server-badge"><span class="online-dot"></span>Sunucu</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>Araç ve ekipmanların yükleniyor...</div></section>`;
 }
 const g=onlineGarageState||{},vehicles=g.vehicles||[],equipment=g.equipment||[],vc=g.vehicle_catalog||[],ec=g.equipment_catalog||[],stats=g.gear_stats||{};
 return `<section class="card pad"><div class="section-head"><h2>Gerçek Garaj & Ekipman</h2><span class="badge">${vehicles.length}/${Number(g.capacity||1)} araç</span></div>
 <div class="server-lock"><b>🚘 Envanter sunucudadır.</b> Araç ve ekipman satın alma, aktif araç ve kuşanılan ekipman PvP hesaplarında doğrudan backend tarafından kullanılır.</div>
 <div class="quick-grid" style="margin-top:12px"><div class="quick"><b>${Number(stats.power||0)}</b><small>Güç</small></div><div class="quick"><b>${Number(stats.defense||0)}</b><small>Savunma</small></div><div class="quick"><b>${Number(stats.stealth||0)}</b><small>Gizlilik</small></div><div class="quick"><b>${Number(stats.escape||0)}</b><small>Kaçış</small></div></div>
 <div class="section-head" style="margin-top:16px"><h2>Araçların</h2><span class="badge">${state.car||'Aktif araç yok'}</span></div>
 <div class="server-catalog">${vehicles.length?vehicles.map(v=>`<div class="server-item ${v.active?'active':''}"><h4>${v.active?'★ ':''}${esc(v.name)}</h4><p class="small">Hız ${Number(v.speed||0)} • Dayanıklılık ${Number(v.durability||0)} • Kaçış ${Number(v.escape||0)} • Prestij +${Number(v.prestige||0)}<br>Kondisyon %${Number(v.condition||100)}</p><button class="btn ${v.active?'':'gold'}" ${v.active?'disabled':''} onclick="setRealActiveVehicle('${v.id}')">${v.active?'AKTİF':'AKTİF YAP'}</button></div>`).join(''):'<div class="online-empty">Henüz sunucu aracın yok.</div>'}</div>
 <div class="section-head" style="margin-top:16px"><h2>Araç Satın Al</h2><span class="badge">Garaj ${vehicles.length}/${Number(g.capacity||1)}</span></div>
 <div class="server-catalog">${vc.map(v=>`<div class="server-item"><h4>${esc(v.name)}</h4><p class="small">${esc(v.description||'')}<br>Hız ${Number(v.speed||0)} • Dayanıklılık ${Number(v.durability||0)} • Kaçış ${Number(v.escape||0)} • ${esc(v.required_rank)}</p><button class="btn ${state.cash>=Number(v.price||0)&&vehicles.length<Number(g.capacity||1)?'gold':''}" ${state.cash<Number(v.price||0)||vehicles.length>=Number(g.capacity||1)?'disabled':''} onclick="buyRealVehicle('${v.id}')">${fmt(Number(v.price||0))}</button></div>`).join('')}</div>
 <div class="section-head" style="margin-top:16px"><h2>Ekipmanların</h2><span class="badge">${equipment.length}/18</span></div>
 <div class="server-catalog">${equipment.length?equipment.map(e=>`<div class="server-item ${e.equipped?'equipped':''}"><h4>${e.equipped?'★ ':''}${esc(e.name)}</h4><p class="small">${esc(e.slot)} • Güç ${Number(e.power||0)} • Savunma ${Number(e.defense||0)} • Gizlilik ${Number(e.stealth||0)} • Kaçış ${Number(e.escape||0)}</p><button class="btn ${e.equipped?'ghost':'gold'}" onclick="${e.equipped?`unequipRealItem('${e.id}')`:`equipRealItem('${e.id}')`}">${e.equipped?'ÇIKAR':'KUŞAN'}</button></div>`).join(''):'<div class="online-empty">Henüz ekipmanın yok.</div>'}</div>
 <div class="section-head" style="margin-top:16px"><h2>Ekipman Satın Al</h2></div>
 <div class="server-catalog">${ec.map(e=>`<div class="server-item"><h4>${esc(e.name)}</h4><p class="small">${esc(e.description||'')}<br>${esc(e.slot)} • Güç ${Number(e.power||0)} • Savunma ${Number(e.defense||0)} • ${esc(e.required_rank)}</p><button class="btn ${state.cash>=Number(e.price||0)&&equipment.length<18?'gold':''}" ${state.cash<Number(e.price||0)||equipment.length>=18?'disabled':''} onclick="buyRealEquipment('${e.id}')">${fmt(Number(e.price||0))}</button></div>`).join('')}</div>
 </section>`;
}
async function buyRealVehicle(id){
 if(onlineBusy)return;onlineBusy=true;
 try{const {data,error}=await sb.rpc('buy_vehicle',{p_vehicle_id:id});if(error)throw error;if(!data?.ok){showInfo('Araç alınamadı',serverErrorMessage(data,'Araç'));return}await Promise.all([syncOnlineState(false),loadOnlineGarage(false)]);renderGame();showInfo('Araç garajda','Satın alma sunucuda tamamlandı.');}
 catch(e){showInfo('Garaj hatası',onlineErrText(e))}finally{onlineBusy=false}
}
