const ONLINE_OPS={
 wedding_raid:{name:'Düğün Baskını',desc:'Hızlı ama kalabalık bir operasyon.',min:4,energy:18,cost:18000,rep:90,risk:38},
 mansion_raid:{name:'Malikâne Baskını',desc:'Daha ağır koruma ve daha yüksek kasa.',min:5,energy:24,cost:32000,rep:140,risk:45},
 gang_war:{name:'Çete Savaşı',desc:'Ailenin en sert grup operasyonu.',min:8,energy:32,cost:60000,rep:220,risk:55}
};
function opName(type){return ONLINE_OPS[type]?.name||type}
async function loadOnlineOps(render=true){
 if(!onlineSession)return;
 try{
   const [opsRes,statRes]=await Promise.all([sb.rpc('my_family_operations'),sb.rpc('my_group_operation_stats')]);
   if(opsRes.error)throw opsRes.error;if(statRes.error)throw statRes.error;
   onlineOpsState=opsRes.data||{};onlineOpsStats=statRes.data||{wins:0,losses:0};onlineOpsLoaded=true;
   state.groupOpsWon=Number(onlineOpsStats.wins||0);state.groupOpsLost=Number(onlineOpsStats.losses||0);
   if(render&&currentPage==='ops')renderGame();
 }catch(e){console.warn('ops',e);if(render)showInfo('Operasyonlar yüklenemedi',onlineErrText(e))}
}
function onlineOpsView(){
 if(!onlineOpsLoaded){
   setTimeout(()=>loadOnlineOps(true),20);
   return `<section class="card pad"><div class="section-head"><h2>Gerçek Grup Operasyonları</h2><span class="server-badge"><span class="online-dot"></span>Sunucu</span></div><div class="online-empty"><div class="spinner" style="margin:0 auto 12px"></div>Aile operasyonları yükleniyor...</div></section>`;
 }
 const s=onlineOpsState||{},active=s.active||null,hist=s.history||[],role=s.role;
 const cd=s.cooldown?.cooldown_until?Math.max(0,Date.parse(s.cooldown.cooldown_until)-Date.now()):0;
 const canCreate=!!s.family_id&&['Aile Lideri','Sağ Kol','Yönetici'].includes(role)&&!active&&cd<=0;
 const me=onlineSession?.user?.id;
 return `<section class="card pad"><div class="section-head"><h2>Gerçek Grup Operasyonları</h2><span class="badge">✅ ${Number(onlineOpsStats.wins||0)} • ❌ ${Number(onlineOpsStats.losses||0)}</span></div>
 <div class="server-lock"><b>⚔ Ekip gerçek aile üyelerinden oluşur.</b> Bütün üyeler yeterli enerjiye sahip olmalı ve son 10 dakikada online görünmelidir. Sonuç, yaralanma ve mahkeme dosyaları sunucuda hesaplanır.</div>
 ${!s.family_id?`<div class="online-empty" style="margin-top:12px">Grup operasyonu için gerçek bir aileye katılmalısın.</div>`:''}
 ${active?`<div class="ops-live" style="margin-top:12px"><div class="kicker">EKİP TOPLANIYOR</div><h2>${opName(active.operation_type)}</h2><div class="job-meta"><span class="chip">Ekip ${(active.members||[]).length}/${Number(active.min_crew||0)}</span><span class="chip">Enerji ${Number(active.energy_cost||0)}</span><span class="chip">Kasa ${fmt(Number(active.treasury_cost||0))}</span><span class="chip">İtibar ${Number(active.base_rep||0)}</span></div>
 <div style="display:grid;gap:7px;margin:10px 0">${(active.members||[]).map(m=>`<div class="ops-member"><b>${m.user_id===me?'★ ':''}${esc(m.username)}</b><div class="small">${esc(m.rank)} • ⭐ ${Number(m.reputation||0).toLocaleString('tr-TR')} • ${onlineAgo(m.last_seen)}</div></div>`).join('')}</div>
 <div class="splash-actions">${(active.members||[]).some(m=>m.user_id===me)?(active.created_by===me?`<button class="btn red" onclick="startRealFamilyOperation('${active.id}')">OPERASYONU BAŞLAT</button><button class="btn ghost" onclick="cancelRealFamilyOperation('${active.id}')">İPTAL ET</button>`:`<button class="btn ghost" onclick="leaveRealFamilyOperation('${active.id}')">EKİPTEN AYRIL</button>`):`<button class="btn gold" onclick="joinRealFamilyOperation('${active.id}')">EKİBE KATIL</button>`}</div></div>`:''}
 <div class="section-head" style="margin-top:15px"><h2>Yeni Operasyon</h2><span class="badge">${cd>0?'Bekleme '+Math.ceil(cd/60000)+' dk':role||'Ailesiz'}</span></div>
 <div class="cards3">${Object.entries(ONLINE_OPS).map(([id,o])=>`<article class="image-card"><div class="pic" style="background-image:url('${IMG[id==='wedding_raid'?'wedding.webp':id==='mansion_raid'?'property.webp':'result_police.webp']}')">${rainHTML(7)}</div><div class="body"><h3>${o.name}</h3><p>${o.desc}</p><div class="job-meta"><span class="chip">Ekip ${o.min}+</span><span class="chip">Enerji ${o.energy}</span><span class="chip">${fmt(o.cost)} Aile Kasası</span><span class="chip">⭐ ${o.rep}</span></div><button class="btn ${canCreate?'red':''}" ${canCreate?'':'disabled'} onclick="createRealFamilyOperation('${id}')">EKİP KUR</button></div></article>`).join('')}</div>
 <div class="section-head" style="margin-top:16px"><h2>Operasyon Geçmişi</h2></div>
 ${hist.length?`<div class="list">${hist.map(h=>`<div class="list-row"><div><h4>${h.success?'✅':'❌'} ${opName(h.operation_type)}</h4><p>${new Date(h.completed_at).toLocaleString('tr-TR')} • Ekip ${Number(h.crew||0)} • Başarı %${Number(h.success_chance||0)} • Polis ${Number(h.police_hits||0)}</p></div><b>${h.success?fmt(Number(h.reward||0)):'Geri çekildi'}</b></div>`).join('')}</div>`:`<div class="online-empty">Henüz tamamlanan aile operasyonu yok.</div>`}
 </section>`;
}
