function load(){
 try{
   const raw=localStorage.getItem('kanunsuz_v1261') || localStorage.getItem('kanunsuz_v126') || localStorage.getItem('kanunsuz_v125') || localStorage.getItem('kanunsuz_v124') || localStorage.getItem('kanunsuz_v123') || localStorage.getItem('kanunsuz_v122') || localStorage.getItem('kanunsuz_v121') || localStorage.getItem('kanunsuz_v12') || localStorage.getItem('kanunsuz_v113') || localStorage.getItem('kanunsuz_v112');
   if(raw) state={...defaultState,...JSON.parse(raw)};
 }catch(e){}
 ensureChatSeed();
}
function save(){localStorage.setItem('kanunsuz_v1261',JSON.stringify(state))}
function fmt(n){return Math.round(n).toLocaleString('tr-TR')+' TL'}
function time(){return new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}
function addLog(msg){state.logs.unshift({t:time(),m:msg});state.logs=state.logs.slice(0,80);save()}
function addNews(msg){state.news.unshift(msg);state.news=state.news.slice(0,12);save()}
function ensureChatSeed(){
 if(!Array.isArray(state.chatMessages)) state.chatMessages=[];
 if(!state.chatTab) state.chatTab='world';
 if(state.chatMessages.length===0){
   state.chatMessages=[
     {channel:'world',user:'Kör Rasim',text:'Karaköy gece yine sıcak. Ağzı olan değil, sözü olan konuşsun.',t:'21:05'},
     {channel:'world',user:'Madam Leyla',text:'Galata tarafında boş konuşan çok. İşi olan yanıma gelsin.',t:'21:08'},
     {channel:'family',user:'Aile Hattı',text:'Bir aileye katıldığında burada iç haberleşme açılır.',t:'21:10'},
     {channel:'private',user:'Sistem',text:'Özel mesaj sistemi şimdilik demo çalışıyor.',t:'21:12'}
   ];
 }
}
function rankIndex(name){return RANKS.findIndex(r=>r.name===name)}
function nextRankData(){
 const i=rankIndex(state.rank);
 if(i<0 || i>=RANKS.length-1)return null;
 return RANKS[i+1];
}
function wealth(){return (state.cash||0)+(state.bank||0)}
function getPromotionStatus(){
 const next=nextRankData();
 if(!next)return {ready:false,next:null,reasons:['En yüksek rütbe']};
 if(next.name==='Konsey Başı')return {ready:false,next,reasons:['Siyah Konsey ve Konsey sistemi gerekli']};
 const p=PROMOTIONS[next.name];
 const reasons=[];
 if(state.rep<next.rep)reasons.push(`${next.rep.toLocaleString('tr-TR')} itibar`);
 if((state.jobsDone||0)<p.jobs)reasons.push(`${p.jobs} başarılı iş`);
 if(p.needCar && !state.car)reasons.push('En az 1 araç');
 if(p.needFamily && !state.family)reasons.push('Bir aileye üyelik');
 if(p.properties && (state.properties||[]).length<p.properties)reasons.push(`${p.properties} mülk`);
 if(p.opsWon && (state.groupOpsWon||0)<p.opsWon)reasons.push(`${p.opsWon} başarılı grup operasyonu`);
 if(p.wealth && wealth()<p.wealth)reasons.push(`${fmt(p.wealth)} toplam servet`);
 return {ready:reasons.length===0,next,p,reasons};
}
function rankUp(){
 const s=getPromotionStatus();
 if(s.ready && state.promotionNotifiedFor!==s.next.name){
   state.promotionNotifiedFor=s.next.name;
   addLog('Terfi Görevi açıldı: '+s.p.title);
   addNews(state.name+' için '+s.next.name+' terfi sınavının açıldığı konuşuluyor.');
 }
}
function startPromotion(){
 if(onlineSession){attemptRealPromotion();return}
 const s=getPromotionStatus();
 if(!s.next)return;
 if(s.next.name==='Konsey Başı'){showInfo('Konsey Başı kilitli','Bu rütbe normal itibarla alınamaz. Siyah Konsey sandalyesi ve 7 günlük Konsey Başı seçimini kazanman gerekir.');return}
 if(!s.ready){showInfo('Terfi henüz hazır değil','Eksik şartlar: '+s.reasons.join(' • '));return}
 if(Date.now()<(state.promotionCooldownUntil||0)){
   showInfo('Terfi sınavı beklemede','Yeni deneme için biraz beklemen gerekiyor.');return
 }
 if(state.energy<s.p.energy){showInfo('Enerji yetersiz','Terfi görevi için '+s.p.energy+' enerji gerekiyor.');return}
 if(state.cash<s.p.cost){showInfo('Hazırlık bütçesi yetersiz',fmt(s.p.cost)+' gerekiyor.');return}
 state.energy-=s.p.energy;
 state.cash-=s.p.cost;
 state.promotionAttempts=(state.promotionAttempts||0)+1;

 let chance=s.p.chance;
 chance+=Math.min(8,Math.floor((state.groupOpsWon||0)/3));
 chance-=Math.min(10,Math.floor((state.convictions||0)*2));
 chance=Math.max(45,Math.min(90,chance));

 if(Math.random()*100<chance){
   const old=state.rank;
   state.rank=s.next.name;
   state.promotionNotifiedFor=null;
   state.rep+=Math.max(5,Math.round(s.next.rep*.002));
   addLog('Terfi görevi başarıldı: '+old+' → '+state.rank);
   addNews(state.name+' artık '+state.rank+' rütbesinde.');
   showPromotionResult(true,s.p.title,state.rank,chance);
 }else{
   const penalty=Math.max(3,Math.round(s.next.rep*.003));
   state.rep=Math.max(0,state.rep-penalty);
   state.heat=Math.min(100,state.heat+5);
   state.promotionCooldownUntil=Date.now()+10*60*1000; // prototipte 10 dk
   addLog('Terfi görevi başarısız oldu. '+penalty+' itibar kaybettin.');
   showPromotionResult(false,s.p.title,s.next.name,chance);
 }
 save();
}
function showPromotionResult(ok,title,rank,chance){
 document.body.insertAdjacentHTML('beforeend',`<div class="modal ${ok?'success':'police'}" id="resultModal"><div class="modal-box"><div class="modal-visual" style="background-image:url('${IMG[ok?'result_success.webp':'result_police.webp']}')">${rainHTML(14)}</div><div class="modal-content">
 <div class="kicker">TERFİ GÖREVİ</div><h2>${ok?'Rütben yükseldi.':'Sınavı geçemedin.'}</h2>
 <p class="small">${title}<br>${ok?`Yeni rütbe: ${rank}`:`Hedef rütbe: ${rank}`} • Başarı ihtimali %${chance}</p>
 <div class="modal-actions"><button class="btn gold" onclick="closeResult();renderGame()">DEVAM ET</button></div></div></div></div>`);
}
function resetDailyRepIfNeeded(){
 const today=new Date().toISOString().slice(0,10);
 if(!state.jobRepDaily || state.jobRepDaily.date!==today) state.jobRepDaily={date:today,counts:{}};
}
function jobRepReward(j){
 resetDailyRepIfNeeded();
 const counts=state.jobRepDaily.counts;
 const count=counts[j.id]||0;
 counts[j.id]=count+1;

 if((j.rep||0)===0){
   // Küçük suçların sadece çok düşük ihtimalle 1 itibar vermesi.
   if(count<10 && Math.random()*100<(j.rareRep||0)) return 1;
   return 0;
 }
 // Aynı işi spamlamak itibarı hızla kurutur.
 if(count<5)return j.rep;
 if(count<10)return Math.max(0,Math.floor(j.rep*.5));
 return 0;
}
function pct(n){return Math.max(0,Math.min(100,n))}
function rainHTML(count=55){
 let s='<div class="rain-layer">';
 for(let i=0;i<count;i++){const left=Math.random()*100,d=.7+Math.random()*1.4,delay=-Math.random()*2;s+=`<i style="left:${left}%;animation-duration:${d}s;animation-delay:${delay}s"></i>`}
 return s+'</div>';
}
