let introScene=0;
let introTimer=null;
let titleTimer=null;
let introResumeAfter=false;
let introMusicBlocked=false;

const INTRO_SCENES=[
 {img:'cin_intro_1.webp',ms:7600,kicker:'İSTANBUL • 1994',title:'Gece yarısını geçti.',body:'Uzakta bir vapur düdüğü. Yağmur Karaköy taşlarına vuruyor. Bu şehir uyumuyor. Sadece sesini kısıyor.',quote:'“İstanbul’da gece yarısını geçti…”'},
 {img:'cin_intro_2.webp',ms:7800,kicker:'KARAKÖY RIHTIMI',title:'Cebinde 750 TL.',body:'Araban yok. Ailen yok. Seni tanıyan yok. Limanda günübirlik bir iş ararken karanlığın içinden bir adam çıkıyor.',quote:'Kör Rasim: “İş mi arıyorsun?”'},
 {img:'intro_letter.webp',ms:8000,kicker:'İLK TEMAS',title:'Bazı işler para kazandırmaz.',body:'Rasim ceketinden mühürlü bir zarf çıkarıyor. Üzerinde isim yok. Yalnızca küçük siyah bir işaret var: VII.',quote:'“Galata’ya çıkacaksın. Mavi bir kapı göreceksin.”'},
 {img:'cin_intro_4.webp',ms:8200,kicker:'YEDİ SANDALYE',title:'Bir sandalye boş.',body:'Şehrin çok üzerinde başka bir masa var. Kim olduklarını bilmiyorsun. Henüz onların da seni tanıdığını bilmiyorsun.',quote:'Karanlıktaki ses: “Başladı.”'}
];

function ensureIntroAudio(){
 let a=document.getElementById('introMusic');
 if(!a){
   a=document.createElement('audio');
   a.id='introMusic';
   a.src=INTRO_MUSIC;
   a.loop=true;
   a.preload='auto';
   a.volume=.38;
   a.setAttribute('playsinline','');
   document.body.appendChild(a);
 }
 return a;
}
async function startIntroMusic(){
 const a=ensureIntroAudio();
 try{
   await a.play();
   introMusicBlocked=false;
 }catch(e){
   introMusicBlocked=true;
 }
 updateMusicToggle();
 if(introMusicBlocked){
   const b=document.getElementById('musicToggle');
   if(b)b.textContent='🔇 Müziği Aç';
 }
}
function updateMusicToggle(){
 const b=document.getElementById('musicToggle');
 if(!b)return;
 const a=document.getElementById('introMusic');
 b.textContent=(a && !a.paused)?'🔊 Müzik':'🔇 Müziği Aç';
}
function toggleIntroMusic(){
 const a=ensureIntroAudio();
 if(a.paused){
   a.play().then(()=>{introMusicBlocked=false;updateMusicToggle()}).catch(()=>{introMusicBlocked=true;updateMusicToggle()});
 }else{
   a.pause();updateMusicToggle();
 }
}
function stopIntroMusic(){
 const a=document.getElementById('introMusic');
 if(!a || a.paused)return;
 const start=a.volume;
 let step=0;
 const f=setInterval(()=>{
   step++;
   a.volume=Math.max(0,start*(1-step/12));
   if(step>=12){clearInterval(f);a.pause();a.currentTime=0;a.volume=.38}
 },70);
}
function clearIntroTimers(){
 if(introTimer)clearTimeout(introTimer);
 if(titleTimer)clearTimeout(titleTimer);
 introTimer=null;titleTimer=null;
}
function bootIntro(forceNew=false){
 clearIntroTimers();
 introResumeAfter=!forceNew && !!state.name;
 introScene=0;
 playCinematicIntro();
 startIntroMusic();
}
function newGame(){
 state={...defaultState,lastIncome:Date.now()};
 save();
 introResumeAfter=false;
 introScene=0;
 playCinematicIntro();
 startIntroMusic();
}
function playCinematicIntro(){
 clearIntroTimers();
 const s=INTRO_SCENES[introScene];
 const last=introScene===INTRO_SCENES.length-1;
 document.getElementById('app').innerHTML=`<section class="cinema-screen scene-${introScene}" style="--sceneMs:${s.ms}ms">
 <div class="cinema-bg" style="background-image:url('${IMG[s.img]}')"></div>
 <div class="cinema-vignette"></div><div class="cinema-fog"></div><div class="cinema-light"></div>${rainHTML(78)}<div class="noise"></div>
 <button class="music-toggle" id="musicToggle" onclick="toggleIntroMusic()">🔊 Müzik</button>
 <button class="cinema-skip" onclick="skipAutoIntro()">İntroyu Atla</button>
 <div class="cinema-copy">
   <div class="kicker">${s.kicker}</div>
   <h2>${s.title}</h2>
   <p>${s.body}</p>
   <p class="cinema-quote">${s.quote}</p>
   <div class="cinema-nav">
    <div class="cinema-dots">${INTRO_SCENES.map((_,i)=>`<i class="cinema-dot ${i===introScene?'on':''}"></i>`).join('')}</div>
    <div class="cinema-progress"><i></i></div>
    ${introScene>0?`<button class="btn ghost" onclick="prevIntroScene()">GERİ</button>`:''}
    <button class="btn gold" onclick="${last?'showTitleIntro()':'nextIntroScene()'}">${last?'BAŞLIĞA GEÇ':'İLERİ'}</button>
   </div>
 </div></section>`;
 updateMusicToggle();
 introTimer=setTimeout(()=>{last?showTitleIntro():nextIntroScene()},s.ms);
}
function nextIntroScene(){
 clearIntroTimers();
 if(introScene<INTRO_SCENES.length-1){introScene++;playCinematicIntro()}
 else showTitleIntro();
}
function prevIntroScene(){
 clearIntroTimers();
 if(introScene>0){introScene--;playCinematicIntro()}
}
function showTitleIntro(){
 clearIntroTimers();
 document.getElementById('app').innerHTML=`<section class="cinema-screen title-scene" style="--sceneMs:5200ms">
 <div class="cinema-bg" style="background-image:url('${IMG['cin_intro_1.webp']}')"></div><div class="cinema-vignette"></div><div class="cinema-fog"></div><div class="cinema-light"></div>${rainHTML(82)}<div class="noise"></div>
 <button class="music-toggle" id="musicToggle" onclick="toggleIntroMusic()">🔊 Müzik</button>
 <button class="cinema-skip" onclick="skipAutoIntro()">İntroyu Atla</button>
 <div class="cinema-copy"><div class="kicker">BU ŞEHİRDE HERKES BİR YERE BAĞLIDIR</div>
 <div class="cinema-title-logo">KANUNSUZ</div><h2 style="color:var(--gold);letter-spacing:.16em">İSTANBUL 1994</h2>
 <p class="cinema-quote">“Sen kime bağlısın?”</p>
 <div class="cinema-nav"><div class="cinema-progress"><i></i></div><button class="btn ghost" onclick="showRulesModal()">OYUN KURALLARI</button></div>
 </div></section>`;
 updateMusicToggle();
 titleTimer=setTimeout(finishAutoIntro,5200);
}
function finishAutoIntro(){
 clearIntroTimers();
 stopIntroMusic();
 onlineGate();
}
function skipAutoIntro(){
 clearIntroTimers();
 stopIntroMusic();
 onlineGate();
}

