function renderGame(){
 if(!onlineSession)collectPassive();
 if(state.awaitingTrial){currentPage='court'}
 else if(Date.now()<state.jailUntil){currentPage='jail'}
 else if(state.dead && !['cemetery','chat','news','notifications','families','profile'].includes(currentPage)){currentPage='cemetery'}
 else if(Date.now()<state.hospitalUntil){currentPage='hospital'}
 document.getElementById('app').innerHTML=`<section class="game"><div class="shell">
 <div class="topbar"><div class="toprow"><div class="mini-logo">KANUNSUZ <span>1994</span></div>${statHTML()}</div></div>
 <div class="main-grid"><aside class="side">${navHTML()}</aside><main class="content" id="content">${view(currentPage)}</main></div>
 </div>${bottomNav()}</section>`;
 save();
}
function go(p){
 if(state.awaitingTrial && p!=='court'){currentPage='court';renderGame();return}
 if(Date.now()<state.jailUntil && p!=='jail'){currentPage='jail';renderGame();return}
 currentPage=p;
 if(onlineSession&&p==='notifications')loadOnlineNotifications(false);
 if(onlineSession&&p==='news')loadOnlineWorldNews(false);
 if(onlineSession&&p==='ranking')loadOnlineRankings(false);
 if(onlineSession&&p==='council')loadOnlineCouncil(false);
 if(onlineSession&&p==='garage')loadOnlineGarage(false);
 if(onlineSession&&p==='ops')loadOnlineOps(false);
 if(onlineSession&&p==='cemetery')loadOnlineCemetery(false);
 renderGame()
}
